// UpdateRoomTypeOutputOnly queues UpdateOutputOnly; in.Etag, when set, guards
// it, and a guarded update runs ahead of the batch (see graphQLBatch).
func (b *graphQLBatch) UpdateRoomTypeOutputOnly(in *room_typev1.RoomType, paths []string) {
	if len(paths) == 0 {
		b.u.Fail(fmt.Errorf("%w: UpdateOutputOnly needs the fields to write", repox.ErrInvalidArgument))
		return
	}
	if _, err := repox.SplitName(in.GetName(), "hotels", "roomTypes"); err != nil {
		b.u.Fail(err)
		return
	}
	r := &GraphQLRoomTypeRepository{Svc: b.svc}
	patch := roomTypeToOutputPatch(in, paths)
	patch.Etag = graphql.Value(repox.NewULID())
	patch.UpdateTime = graphql.Value(tsToStr(timestamppb.New(time.Now().UTC())))
	b.u.Record(repox.Change{Type: "hotel.opentravel.org/RoomType", Name: in.GetName(), Op: repox.ChangeUpdate, Record: in, LoadPrior: repox.PriorOf(in.GetName(), getRoomType)})
	if etag := in.GetEtag(); etag != "" {
		b.u.QueueGraphQLAhead(func(ctx context.Context) error {
			id, err := b.rowID(ctx, in.GetName(), r.rowID)
			if err != nil {
				return err
			}
			_, err = b.svc.Mutation.Roomtype.Resource.UpdateIfMatch(ctx, id, patch, resourceql.Etag.Eq(etag))
			return mapGraphQLErr(err)
		})
		return
	}
	b.u.QueueGraphQL(func(ctx context.Context, ops *repox.Ops) (repox.Check, error) {
		id, err := b.rowID(ctx, in.GetName(), r.rowID)
		if err != nil {
			return nil, err
		}
		ops.Add(b.svc.Mutation.Roomtype.Resource.UpdateOp(id, patch, new(resourceql.UpdateRoomtypeResourceByIdResponse)))
		return nil, nil
	})
}

// DeleteRoomType queues a soft delete. A record already deleted or gone is
// not an error.
func (b *graphQLBatch) DeleteRoomType(name string) {
	if _, err := repox.SplitName(name, "hotels", "roomTypes"); err != nil {
		b.u.Fail(err)
		return
	}
	r := &GraphQLRoomTypeRepository{Svc: b.svc, Retention: b.retention}
	queueRoomTypeDelete(b.u, name, false)
	b.u.QueueGraphQL(func(ctx context.Context, ops *repox.Ops) (repox.Check, error) {
		id, err := b.rowID(ctx, name, r.rowID)
		if errors.Is(err, repox.ErrNotFound) {
			return nil, nil
		}
		if err != nil {
			return nil, err
		}
		ops.Add(b.svc.Mutation.Roomtype.Resource.UpdateOp(id, r.deletePatch(), new(resourceql.UpdateRoomtypeResourceByIdResponse), resourceql.Update().PreCheck(resourceql.DeleteTime.IsNull(true))))
		return nil, nil
	})
	b.u.Record(repox.Change{Type: "hotel.opentravel.org/RoomType", Name: name, Op: repox.ChangeDelete, LoadPrior: repox.PriorOf(name, getRoomType)})
}

// PurgeRoomType queues the record's removal for good. A record already
// gone is not an error.
func (b *graphQLBatch) PurgeRoomType(name string) {
	if _, err := repox.SplitName(name, "hotels", "roomTypes"); err != nil {
		b.u.Fail(err)
		return
	}
	r := &GraphQLRoomTypeRepository{Svc: b.svc}
	// A record a referrer in another database or service names is kept, as
	// Purge keeps it. One a foreign key of this database still names fails
	// the commit with repox.ErrForeignKey: the request is one transaction,
	// and the engine cannot skip one of its mutations.
	keep := queueRoomTypePurge(b.u, name)
	b.u.QueueGraphQL(func(ctx context.Context, ops *repox.Ops) (repox.Check, error) {
		if *keep {
			return nil, nil
		}
		id, err := b.rowID(ctx, name, r.rowID)
		if errors.Is(err, repox.ErrNotFound) {
			return nil, nil
		}
		if err != nil {
			return nil, err
		}
		return r.purgeOps(ctx, ops, id)
	})
	b.u.Record(repox.Change{Type: "hotel.opentravel.org/RoomType", Name: name, Op: repox.ChangePurge, LoadPrior: repox.PriorOf(name, getRoomType)})
}
